+const { useState, useEffect, useRef } = React;
+
+const Modal = ({ isOpen, onClose, onConfirm, title, message }) => {
+    const modalRef = useRef(null);
+    const firstElementRef = useRef(null);
+    const lastElementRef = useRef(null);
+
+    useEffect(() => {
+        if (isOpen) {
+            // Focus trapping logic
+            const focusableElements = modalRef.current.querySelectorAll(
+                'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
+            );
+            if (focusableElements.length > 0) {
+                firstElementRef.current = focusableElements[0];
+                lastElementRef.current = focusableElements[focusableElements.length - 1];
+                firstElementRef.current.focus();
+            }
+
+            const handleKeyDown = (e) => {
+                if (e.key === 'Escape') onClose();
+                if (e.key === 'Tab') {
+                    if (e.shiftKey) {
+                        if (document.activeElement === firstElementRef.current) {
+                            e.preventDefault();
+                            lastElementRef.current.focus();
+                        }
+                    } else {
+                        if (document.activeElement === lastElementRef.current) {
+                            e.preventDefault();
+                            firstElementRef.current.focus();
+                        }
+                    }
+                }
+            };
+
+            window.addEventListener('keydown', handleKeyDown);
+            return () => window.removeEventListener('keydown', handleKeyDown);
+        }
+    }, [isOpen, onClose]);
+
+    if (!isOpen) return null;
+
+    return (
+        <div className="modal-overlay" onClick={onClose}>
+            <div 
+                className="modal-content" 
+                ref={modalRef}
+                onClick={(e) => e.stopPropagation()}
+                role="dialog"
+                aria-modal="true"
+                aria-labelledby="modal-title"
+                aria-describedby="modal-description"
+            >
+                <div className="modal-header">
+                    <h2 id="modal-title">{title}</h2>
+                </div>
+                <div className="modal-body">
+                    <p id="modal-description">{message}</p>
+                </div>
+                <div className="modal-footer">
+                    <button className="btn btn-secondary" onClick={onClose}>Cancel</button>
+                    <button className="btn btn-danger" onClick={onConfirm}>Delete</button>
+                </div>
+            </div>
+        </div>
+    );
+};
+
+const App = () => {
+    const [isModalOpen, setIsModalOpen] = useState(false);
+    const triggerRef = useRef(null);
+
+    const openModal = () => setIsModalOpen(true);
+    const closeModal = () => {
+        setIsModalOpen(false);
+        // Return focus to trigger
+        if (triggerRef.current) {
+            triggerRef.current.focus();
+        }
+    };
+
+    const handleDelete = () => {
+        alert("Image deleted (simulated)");
+        closeModal();
+    };
+
+    return (
+        <div className="container">
+            <div className="image-container">
+                <img 
+                    src="https://images.unsplash.com/photo-1550684848-fac1c5b4e853?auto=format&fit=crop&q=80&w=600" 
+                    alt="Dark abstract wallpaper" 
+                    className="preview-image"
+                />
+            </div>
+            <h1>Image Preview</h1>
+            <p style={{ color: '#a0a0a0', marginBottom: '2rem' }}>
+                Abstract geometric patterns in dark shades.
+            </p>
+            <button 
+                className="trigger" 
+                onClick={openModal}
+                ref={triggerRef}
+                aria-haspopup="dialog"
+            >
+                Delete Image
+            </button>
+
+            <Modal 
+                isOpen={isModalOpen}
+                onClose={closeModal}
+                onConfirm={handleDelete}
+                title="Confirm Deletion"
+                message="Are you sure you want to delete this image? This action cannot be undone."
+            />
+        </div>
+    );
+};
+
+const root = ReactDOM.createRoot(document.getElementById('root'));
+root.render(<App />);
+
