            const modalRef = useRef(null);

            useEffect(() => {
                if (isOpen) {
                    const focusableElements = modalRef.current.querySelectorAll(
                        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
                    );
                    const firstElement = focusableElements[0];
                    const lastElement = focusableElements[focusableElements.length - 1];

                    if (firstElement) firstElement.focus();

                    const handleKeyDown = (e) => {
                        if (e.key === 'Escape') onClose();
                        if (e.key === 'Tab') {
                            if (e.shiftKey) {
                                if (document.activeElement === firstElement) {
                                    e.preventDefault();
                                    lastElement.focus();
                                }
                            } else {
                                if (document.activeElement === lastElement) {
                                    e.preventDefault();
                                    firstElement.focus();
                                }
                            }
                        }
                    };

                    window.addEventListener('keydown', handleKeyDown);
                    return () => window.removeEventListener('keydown', handleKeyDown);
                }
            }, [isOpen, onClose]);

            if (!isOpen) return null;

            return (
                <div className="modal-overlay" onClick={onClose}>
                    <div 
                        className="modal-content" 
                        ref={modalRef}
                        onClick={(e) => e.stopPropagation()}
                        role="dialog"
                        aria-modal="true"
                        aria-labelledby="modal-title"
                        aria-describedby="modal-description"
                    >
                        <div className="modal-header">
                            <h2 id="modal-title">{title}</h2>
                        </div>
                        <div className="modal-body">
                            <p id="modal-description">{message}</p>
                        </div>
                        <div className="modal-footer">
                            <button className="btn btn-cancel" onClick={onClose}>Cancel</button>
                            <button className="btn btn-confirm" onClick={onConfirm}>Delete Image</button>
                        </div>
                    </div>
                </div>
            );
        };

        const App = () => {
            const [isModalOpen, setIsModalOpen] = useState(false);
            const triggerRef = useRef(null);

            const openModal = () => setIsModalOpen(true);
            const closeModal = () => {
                setIsModalOpen(false);
                if (triggerRef.current) triggerRef.current.focus();
            };

            const handleDelete = () => {
                console.log("Image deleted");
                setIsModalOpen(false);
                alert("The image has been deleted from your library.");
            };

            return (
                <div className="container">
                    <img 
                        src="https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&q=80&w=800" 
                        alt="Abstract dark background" 
                        className="image-preview"
                    />
                    <div className="content">
                        <h1 className="title">Dark Abstract #42</h1>
                        <p className="description">Added to your library on May 6, 2026</p>
                        <button 
                            className="trigger" 
                            onClick={openModal}
                            ref={triggerRef}
                            aria-haspopup="dialog"
                        >
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                <path d="M3 6h18m-2 0v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6m3 0V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2M10 11v6M14 11v6" />
                            </svg>
                            Delete from Library
                        </button>
                    </div>

                    <Modal 
                        isOpen={isModalOpen}
                        onClose={closeModal}
                        onConfirm={handleDelete}
                        title="Delete Image?"
                        message="Are you sure you want to delete this image? This action cannot be undone and will permanently remove it from your library."
                    />
                </div>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
</html>
